def caponLocalRademacher (m : ℕ) (root : Fin (2 ^ m))
    (p : ℝ≥0∞) [Fact (1 ≤ p)] (n : ℕ) : Lp ℝ p unitIntervalMeasure :=
  ∑ k ∈ caponLocalCells m root n, dyadicHaar ℝ p ⟨m + n, k⟩

